from collections import defaultdict, deque

def topological_sort(graph, in_degree, n):
    queue = deque([node for node in graph if in_degree[node] == 0])
    visited = []

    while queue:
        if len(queue) > 1:
            return None  # More than one possible order

        node = queue.popleft()
        visited.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(visited) == n:
        return visited
    else:
        return None

def main():
    while True:
        n = int(input())
        if n == 0:
            break

        packages = defaultdict(list)
        in_degree = defaultdict(int)
        all_packages = set()

        for _ in range(n):
            line = input().split()
            package = line[0]
            dependencies = line[1:]
            packages[package] = dependencies
            for dep in dependencies:
                in_degree[dep] += 1
            all_packages.add(package)

        # Check for cycles
        for package in all_packages:
            for dep in packages[package]:
                if package in packages[dep]:
                    print('cannot be ordered')
                    break

        # Topological sort
        result = topological_sort(packages, in_degree, n)
        if result:
            print('\n'.join(result))
        else:
            print('cannot be ordered')

        print()

if __name__ == "__main__":
    main()
